select n.nspname as schema_name, p.proname as function_name,pg_get_function_identity_arguments(p.oid) as arguments,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='public' and p.proname in ('admin_insert_user','restore_payment','soft_delete_payment','purchase_gamification_item','equip_gamification_item','unequip_gamification_item')) or (n.nspname='security' and p.proname in ('is_admin','is_staff','current_role')) order by n.nspname,p.proname,arguments;
